function SumOddElementsInEvenPositions(lst: seq<int>): int
    requires |lst| > 0 // The list must be non-empty
{
    var total := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst| // i is within bounds of the list
        invariant total == SumOddElementsInEvenPositions(lst[0..i]) // Total is the correct sum for the first i elements
    {
        if i % 2 == 0 && lst[i] % 2 != 0 {
            total := total + lst[i];
        }
        i := i + 1;
    }
    return total;
}
